    "lawName": "Constituição do Estado de São Paulo (CESP/1989)",
    "article": "Artigo 271",
    "title": "Constituição de São Paulo (CESP/1989) - Artigo 271",
    "content": "O Estado destinará quantia não inferior a um por cento de sua receita corrente para fomento à pesquisa científica e tecnológica, repassando-a mensalmente à Fundação de Amparo à Pesquisa do Estado de São Paulo (FAPESP).",
